'use strict';

function compileCatalog(items) {
  if (!Array.isArray(items)) {
    throw new TypeError('items must be an array');
  }

  const result = new Map();
  for (const item of items) {
    if (
      item === null ||
      typeof item !== 'object' ||
      typeof item.code !== 'string' ||
      item.code.length === 0 ||
      !Array.isArray(item.aliases) ||
      !item.aliases.every((alias) => typeof alias === 'string' && alias.length > 0)
    ) {
      throw new TypeError('invalid item');
    }

    const names = [item.code, ...item.aliases.map((alias) => alias.toLowerCase())];
    for (const name of names) {
      if (result.has(name)) {
        throw new RangeError('duplicate catalog name');
      }
      result.set(name, item.code);
    }
  }
  return result;
}

module.exports = { compileCatalog };

