'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['compileCatalog']);
assert.strictEqual(typeof api.compileCatalog, 'function');
const { compileCatalog } = api;

const empty = compileCatalog([]);
assert.ok(empty instanceof Map);
assert.strictEqual(empty.size, 0);

const items = [
  { code: 'A', aliases: ['alpha', 'a'] },
  { code: 'b', aliases: ['B', 'beta'] },
  { code: 'C', aliases: [] }
];
const snapshot = JSON.parse(JSON.stringify(items));
const catalog = compileCatalog(items);
assert.ok(catalog instanceof Map);
assert.deepStrictEqual([...catalog.entries()], [
  ['A', 'A'],
  ['alpha', 'A'],
  ['a', 'A'],
  ['b', 'b'],
  ['B', 'b'],
  ['beta', 'b'],
  ['C', 'C']
]);
assert.deepStrictEqual(items, snapshot);

for (const invalid of [
  null,
  {},
  [null],
  [{}],
  [{ code: '', aliases: [] }],
  [{ code: 1, aliases: [] }],
  [{ code: 'A', aliases: 'alpha' }],
  [{ code: 'A', aliases: [''] }],
  [{ code: 'A', aliases: [2] }]
]) {
  assert.throws(() => compileCatalog(invalid), TypeError);
}

for (const collision of [
  [{ code: 'A', aliases: [] }, { code: 'A', aliases: [] }],
  [{ code: 'A', aliases: ['A'] }],
  [{ code: 'A', aliases: ['x', 'x'] }],
  [{ code: 'A', aliases: ['B'] }, { code: 'B', aliases: [] }],
  [{ code: 'A', aliases: ['x'] }, { code: 'B', aliases: ['x'] }],
  [{ code: 'A', aliases: [] }, { code: 'B', aliases: ['A'] }]
]) {
  assert.throws(() => compileCatalog(collision), RangeError);
}

